                                   where n.nspname = 'public' and p.proname = e.name)
      when 'column'   then exists (select 1 from information_schema.columns c
                                   where c.table_schema = 'public' and c.table_name = e.name and c.column_name = e.extra)
      when 'policy'   then exists (select 1 from pg_policies p
                                   where p.schemaname = 'public' and p.tablename = e.name and p.policyname = e.extra)
      else null
    end as present
  from expected e
)
select
  version,
  file,
  case
    when bool_and(kind = 'none') then 'data_only'
    when bool_and(present) then 'already_applied'
    when not bool_or(present) then 'not_applied'
    else 'partial'
  end as verdict,
  count(*) filter (where kind <> 'none') as objects,
  count(*) filter (where present) as present,
  coalesce(string_agg(kind || ' ' || name || case when extra <> '' then '.' || extra else '' end, ', ' order by kind, name)
           filter (where present is false), '') as missing
from checked
group by version, file
order by version;
